    shadowColor: 'shadow-yellow-500/20',
    name: 'Легендарная',
    order: 4
  }
};

export function AchievementCard({ achievement, onClaim }: AchievementCardProps) {
  const config = rarityConfig[achievement.rarity];
  const progressPercentage = Math.min((achievement.progress / achievement.maxProgress) * 100, 100);
  const isCompleted = achievement.completed || achievement.progress >= achievement.maxProgress;
  const canClaim = isCompleted && !achievement.claimed;

  return (
    <Card 
      className={`relative overflow-hidden transition-all duration-300 ${config.borderColor} ${config.shadowColor} ${
        isCompleted ? 'shadow-xl' : 'opacity-85'
      } ${achievement.claimed ? 'opacity-60' : ''}`}
      style={{ backgroundColor: config.color }}
    >
      {/* Progress indicator in top-right corner */}
      <div className="absolute top-3 right-3 bg-green-800 text-yellow-300 font-medium text-sm px-2 py-1 rounded-md shadow-lg shadow-green-500/50 border border-green-400/50">
        {achievement.progress.toLocaleString()}/{achievement.maxProgress.toLocaleString()}
      </div>

      {/* Completed indicator */}
      {achievement.claimed && (
        <div className="absolute top-3 left-3 text-green-400 text-lg">
          ✅
        </div>
      )}

      <CardContent className="p-4">
        <div className="space-y-3">
          {/* Title and Icon - Centered */}
          <div className="text-center space-y-1">
            <div className="text-xl">{achievement.icon}</div>
            <h3 className={`font-bold text-lg ${config.textColor} tracking-wide`}>
              {achievement.title}
            </h3>
          </div>

          {/* Description */}
          <p className={`text-center text-xs ${config.textColor} opacity-90 font-light leading-relaxed`}>
            {achievement.description}
          </p>

          {/* Progress Section */}
          <div className="space-y-2 py-2">
            <div className={`text-sm ${config.textColor} flex items-center justify-between`}>
              <span className="font-bold">📊 Прогресс:</span>
              <span className="font-mono font-bold text-base">
                {progressPercentage.toFixed(0)}%
              </span>
            </div>

            <Progress 
              value={progressPercentage} 
              className="h-1.5 bg-black/40"
            />

            {/* Reward values in place of progress numbers */}
            <div className={`text-sm ${config.textColor} text-center`}>
              <div className="flex items-center justify-center gap-2">
                <span className="font-semibold text-base">
                  {achievement.coinReward.toLocaleString()} <span className="text-green-400 text-sm">₽</span>
                </span>
                <span className="text-blue-400 font-semibold text-base">
                  +{achievement.xpReward} XP
                </span>
              </div>
            </div>
          </div>

          {/* Action Button */}
          <div className="pt-2">
            {achievement.claimed ? (
              <Button 
                disabled
                className="w-full bg-green-600/20 text-green-300 opacity-60 cursor-not-allowed border border-green-600/30 h-8 text-xs"
                size="sm"
              >
                ✅ Получено
              </Button>
            ) : canClaim ? (
              <Button 
                onClick={() => onClaim(achievement.id)}
                className="w-full bg-green-600/80 hover:bg-green-600 text-white font-bold shadow-lg shadow-green-500/40 animate-pulse border border-green-500/50 h-8 text-xs"
                size="sm"
              >
                Получить награду ▶
              </Button>
            ) : (
              <Button 
                disabled
                className="w-full bg-gray-700/50 text-gray-400 opacity-70 cursor-not-allowed border border-gray-600/30 h-8 text-xs"
                size="sm"
              >
                В процессе...
              </Button>
            )}
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

client/src/components/CarConfiguration.t.content:
import React, { useState } from 'react';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group';
import { Label } from '@/components/ui/label';
import { ArrowLeft, ChevronLeft, ChevronRight } from 'lucide-react';
import { getCarEmoji } from '@/utils/imageLoader';

interface CarSpec {
  id: number;
  name: string;
  year: string;
  basePrice: number;
  image: string;
  rating: number;
  category: string;
  bodyType: string;
  engineType: string;
  engineVolume: string;
  basePower: number;
  driveType: string;
  transmission: string;
  fuelConsumption: string;
  baseAcceleration: number;
  baseMaxSpeed: number;
  fuelType: string;
  images: string[];
}

interface ConfigurationProps {
  car: CarSpec;
  onClose: () => void;
  onSave: (carId: number, configuration: string, finalPrice: number) => void;
}

interface TrimLevel {
  name: string;
  multiplier: number;
  powerBonus: number;
  speedBonus: number;
  accelerationBonus: number;
  volumeBonus: number;
  priceIncrease: number;
}

export default function CarConfiguration({ car, onClose, onSave }: ConfigurationProps) {
  const [selectedTrim, setSelectedTrim] = useState('Base');
  const [currentImageIndex, setCurrentImageIndex] = useState(0);

  const trimLevels: TrimLevel[] = [
    {
      name: 'Base',
      multiplier: 1.0,
      powerBonus: 0,
      speedBonus: 0,
      accelerationBonus: 0,
      volumeBonus: 0,
      priceIncrease: 0
    },
    {
      name: 'Comfort',
      multiplier: 1.3,
      powerBonus: 15,
      speedBonus: 10,
      accelerationBonus: -0.3,
      volumeBonus: 0.1,
      priceIncrease: Math.round(car.basePrice * 0.3)
    },
    {
      name: 'Elegance', 
      multiplier: 1.6,
      powerBonus: 30,
      speedBonus: 20,
      accelerationBonus: -0.6,
      volumeBonus: 0.2,
      priceIncrease: Math.round(car.basePrice * 0.6)
    },
    {
      name: 'Premium',
      multiplier: 2.0,
      powerBonus: 50,
      speedBonus: 30,
      accelerationBonus: -1.0,
      volumeBonus: 0.3,
      priceIncrease: Math.round(car.basePrice * 1.0)
    },
    {
      name: 'Sport',
      multiplier: 2.5,
      powerBonus: 80,
      speedBonus: 45,
      accelerationBonus: -1.5,
      volumeBonus: 0.4,
      priceIncrease: Math.round(car.basePrice * 1.5)
    }
  ];

  const getCurrentTrim = () => trimLevels.find(trim => trim.name === selectedTrim) || trimLevels[0];
  const currentTrim = getCurrentTrim();
  const finalPrice = car.basePrice + currentTrim.priceIncrease;

  const getUpdatedSpecs = () => {
    const trim = getCurrentTrim();
    return {
      power: car.basePower + trim.powerBonus,
      maxSpeed: car.baseMaxSpeed + trim.speedBonus,
      acceleration: Math.max(0.1, car.baseAcceleration + trim.accelerationBonus),
      engineVolume: (parseFloat(car.engineVolume) + trim.volumeBonus).toFixed(1)
    };
  };

  const updatedSpecs = getUpdatedSpecs();

  const nextImage = () => {
    setCurrentImageIndex((prev) => (prev + 1) % car.images.length);
  };

  const prevImage = () => {
    setCurrentImageIndex((prev) => (prev - 1 + car.images.length) % car.images.length);
  };

  const getCategoryColor = (category: string) => {
    switch (category) {
      case 'Эконом': return { bg: 'bg-gray-500/20', text: 'text-gray-400', border: 'border-gray-500/30', hex: '#9E9E9E' };
      case 'Бюджет': return { bg: 'bg-green-500/20', text: 'text-green-400', border: 'border-green-500/30', hex: '#4CAF50' };
      case 'Стандарт': return { bg: 'bg-blue-500/20', text: 'text-blue-400', border: 'border-blue-500/30', hex: '#2196F3' };
      case 'Средний класс': return { bg: 'bg-indigo-500/20', text: 'text-indigo-400', border: 'border-indigo-500/30', hex: '#3F51B5' };
      case 'Премиум': return { bg: 'bg-purple-500/20', text: 'text-purple-400', border: 'border-purple-500/30', hex: '#9C27B0' };
      case 'Люкс': return { bg: 'bg-red-500/20', text: 'text-red-400', border: 'border-red-500/30', hex: '#F44336' };
      default: return { bg: 'bg-gray-500/20', text: 'text-gray-400', border: 'border-gray-500/30', hex: '#9E9E9E' };
    }
  };

  const categoryColor = getCategoryColor(car.category);

  return (
    <div className="fixed inset-0 bg-black z-50 overflow-y-auto">
      <div className="min-h-screen p-4 pb-12">
        {/* Header */}
        <div className="mb-6">
          <div className="flex justify-start mb-4">
            <Button
              variant="ghost"
              onClick={onClose}
              className="text-white hover:bg-white/10"
            >
              <ArrowLeft className="h-4 w-4 mr-2" />
              Назад
            </Button>
          </div>
          <h1 className="text-xl font-bold text-white text-center">{car.name}</h1>
        </div>

        {/* Car Images Swiper */}
        <div className="relative mb-6">
          <div className="w-full aspect-square bg-gradient-to-br from-gray-800 to-gray-900 rounded-xl border border-white/20 flex items-center justify-center relative overflow-hidden">
            <img 
              src={car.images[currentImageIndex]} 
              alt={`${car.name} - view ${currentImageIndex + 1}`}
              className="w-full h-full object-cover"
              onError={(e) => {
                const target = e.target as HTMLImageElement;
                const parent = target.parentElement;
                if (parent) {
                  target.style.display = 'none';
                  parent.innerHTML = `<div class="text-8xl">${getCarEmoji(car.id)}</div>`;
                }
              }}
            />

            {car.images.length > 1 && (
              <>
                <Button
                  variant="ghost"
                  size="sm"
                  className="absolute left-2 top-1/2 -translate-y-1/2 text-white hover:bg-white/10 bg-black/30 backdrop-blur-sm"
                  onClick={prevImage}
                >
                  <ChevronLeft className="h-4 w-4" />
                </Button>
                <Button
                  variant="ghost"
                  size="sm"
                  className="absolute right-2 top-1/2 -translate-y-1/2 text-white hover:bg-white/10 bg-black/30 backdrop-blur-sm"
                  onClick={nextImage}
                >
                  <ChevronRight className="h-4 w-4" />
                </Button>
              </>
            )}
          </div>

          {/* Navigation buttons */}
          {car.images.length > 1 && (
            <div className="flex justify-center mt-4 space-x-4">
              <Button
                variant="outline"
                size="sm"
                onClick={prevImage}
                className="bg-gray-800/50 border-gray-600 hover:bg-gray-700/50 text-white px-3 py-1"
              >
                <ChevronLeft size={16} />
              </Button>
              <Button
                variant="outline"
                size="sm"
                onClick={nextImage}
                className="bg-gray-800/50 border-gray-600 hover:bg-gray-700/50 text-white px-3 py-1"
              >
                <ChevronRight size={16} />
              </Button>
            </div>
          )}

          {/* Image Dots */}
          {car.images.length > 1 && (
            <div className="flex justify-center mt-3 gap-2">
              {car.images.map((_, index) => (
                <button
                  key={index}
                  className={`w-2 h-2 rounded-full transition-all ${
                    index === currentImageIndex ? 'bg-white' : 'bg-white/30'
                  }`}
                  onClick={() => setCurrentImageIndex(index)}
                />
              ))}
            </div>
          )}
        </div>

        {/* Car Specifications */}
        <Card className="mb-12 bg-green-900 border border-green-700/30">
          <CardContent className="p-4">
            <h2 className="text-lg font-bold text-white mb-4 text-center">Характеристики</h2>
            <div className="space-y-3">
              <div className="flex justify-between">
                <span className="text-muted-foreground flex items-center">• Марка / модель</span>
                <span className="text-white">{car.name}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-muted-foreground flex items-center">• Год выпуска</span>
                <span className="text-white">{car.year}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-muted-foreground flex items-center">• Тип кузова</span>
                <span className="text-white">{car.bodyType}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-muted-foreground flex items-center">• Тип двигателя</span>
                <span className="text-white">{car.engineType}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-muted-foreground flex items-center">• Объем двигателя</span>
                <span className="text-white">{updatedSpecs.engineVolume}L</span>
              </div>
              <div className="flex justify-between">
                <span className="text-muted-foreground flex items-center">• Мощность (л.с.)</span>
                <span className="text-white">{updatedSpecs.power} л.с.</span>
              </div>
              <div className="flex justify-between">
                <span className="text-muted-foreground flex items-center">• Тип привода</span>
                <span className="text-white">{car.driveType}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-muted-foreground flex items-center">• Коробка передач</span>
                <span className="text-white">{car.transmission}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-muted-foreground flex items-center">• Расход топлива</span>
                <span className="text-white">{car.fuelConsumption}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-muted-foreground flex items-center">• Разгон до 100 км/ч</span>
                <span className="text-white">{updatedSpecs.acceleration.toFixed(1)} сек</span>
              </div>
              <div className="flex justify-between">
                <span className="text-muted-foreground flex items-center">• Макс. скорость</span>
                <span className="text-white">{updatedSpecs.maxSpeed} км/ч</span>
              </div>
              <div className="flex justify-between">
                <span className="text-muted-foreground flex items-center">• Тип топлива</span>
                <span className="text-white">{car.fuelType}</span>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Configuration Selection */}
        <Card className="mb-8 bg-purple-950 border border-purple-700/30">
          <CardContent className="p-4">
            <h2 className="text-lg font-bold text-white mb-2 text-center">Выбери комплектацию:</h2>
            <div className="text-2xl font-bold text-green-400 mb-4 text-center">
              {finalPrice.toLocaleString()} <span className="text-green-700 text-xl">₽</span>
            </div>

            <RadioGroup value={selectedTrim} onValueChange={setSelectedTrim}>
              {trimLevels.map((trim) => {
                const isSelected = selectedTrim === trim.name;
                return (
                  <div key={trim.name} className="flex items-center space-x-4 p-4 rounded-lg bg-white/5 hover:bg-white/10 transition-all duration-300">
                    <RadioGroupItem 
                      value={trim.name} 
                      id={trim.name} 
                      className={`w-5 h-5 border-2 ${isSelected ? 'bg-green-500 border-green-500' : 'border-gray-400'}`}
                    />
                    <Label htmlFor={trim.name} className="flex-1 cursor-pointer">
                      <div className="flex justify-between items-center">
                        <div>
                          <span className="text-white font-medium">{trim.name}</span>
                          {trim.priceIncrease > 0 && (
                            <span className="text-green-400 ml-2">+{trim.priceIncrease.toLocaleString()} <span className="text-green-700 text-sm">₽</span></span>
                          )}
                        </div>
                      </div>
                    </Label>
                  </div>
                );
              })}
            </RadioGroup>

            {/* Save Button inside card - raised up */}
            <Button
              onClick={() => onSave(car.id, selectedTrim, finalPrice)}
              className="w-auto h-10 text-sm font-bold bg-green-600 hover:bg-green-700 text-white mt-6 px-8 mx-auto block"
            >
              Сохранить
            </Button>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

client/src/components/DailyProfitModal.t.content:
import React, { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Card, CardContent } from '@/components/ui/card';
import { Play, Shield } from 'lucide-react';

interface DailyProfitModalProps {
  isOpen: boolean;
  onClose: () => void;
  onClaimProfit: (amount: number, isDoubled: boolean) => void;
  gameState: {
    coins: number;
    level: number;
    totalClicks: number;
    hourlyIncome: number;
    lastProfitClaim?: number;
    dailyStreak?: number;
    timeInGame?: number;
    totalUpgradeSpent?: number;
    ownedCars?: any[];
    selectedStarterCar?: any;
  };
}

interface ProfitBreakdown {
  carFleetIncome: number;
  tuningCashback: number;
  activityBonus: number;
  streakBonus: number;
  total: number;
}

export function DailyProfitModal({ 
  isOpen, 
  onClose, 
  onClaimProfit,
  gameState
}: DailyProfitModalProps) {
  const [timeLeft, setTimeLeft] = useState('');
  const [canClaim, setCanClaim] = useState(false);
  const [canDoubleReward, setCanDoubleReward] = useState(true);

  const PROFIT_INTERVAL = 12 * 60 * 60 * 1000; // 12 hours
  const lastClaimTime = gameState.lastProfitClaim || 0;
  const nextClaimTime = lastClaimTime + PROFIT_INTERVAL;
  const dailyStreak = gameState.dailyStreak || 0;

  // Calculate profit breakdown
  const calculateProfitBreakdown = (): ProfitBreakdown => {
    // 🚗 Доход с автопарка: 1% от общей стоимости текущего автомобиля
    const getCurrentCarValue = () => {
      const currentCar = gameState.ownedCars?.[0] || gameState.selectedStarterCar;
      if (!currentCar) return 50000; // Базовое значение если нет машины

      // Расчет стоимости на основе характеристик автомобиля
      const basePower = currentCar.horsepower || currentCar.basePower || 100;
      const baseAcceleration = parseFloat(currentCar.acceleration || currentCar.baseAcceleration || '12.0');
      const baseMaxSpeed = currentCar.maxSpeed || currentCar.baseMaxSpeed || 180;

      // Формула стоимости: мощность * 500 + (300 - разгон) * 1000 + макс.скорость * 300
      const carValue = Math.floor(
        basePower * 500 + 
        (300 - baseAcceleration) * 1000 + 
        baseMaxSpeed * 300
      );

      return Math.max(carValue, 50000); // Минимум 50,000
    };

    const carValue = getCurrentCarValue();
    const carFleetIncome = Math.floor(carValue * 0.01); // 1% от стоимости автомобиля

    // 💰 Кэшбек с тюнинга: 10% от всех покупок улучшений
    const tuningCashback = Math.floor((gameState.totalUpgradeSpent || 0) * 0.1);

    // 📊 Бонус за активность: +50 за каждую минуту в игре
    const timeInGameMinutes = gameState.timeInGame || 0;
    const activityBonus = Math.floor(timeInGameMinutes * 50);

    // Base total before streak
    const baseTotal = carFleetIncome + tuningCashback + activityBonus;

    // Streak bonus - +5% per day up to 7 days (35% max)
    const streakMultiplier = Math.min(dailyStreak * 0.05, 0.35);
    const streakBonus = Math.floor(baseTotal * streakMultiplier);

    const total = baseTotal + streakBonus;

    return {
      carFleetIncome,
      tuningCashback,
      activityBonus,
      streakBonus,
      total
    };
  };

  const profitBreakdown = calculateProfitBreakdown();

  // Update timer and claim availability
  useEffect(() => {
    const interval = setInterval(() => {
      const now = Date.now();
      const remaining = nextClaimTime - now;

      if (remaining <= 0) {
        setCanClaim(true);
        setTimeLeft('');
      } else {
        setCanClaim(false);
        const hours = Math.floor(remaining / (1000 * 60 * 60));
        const minutes = Math.floor((remaining % (1000 * 60 * 60)) / (1000 * 60));
        setTimeLeft(`${hours}ч ${minutes}м`);
      }
    }, 1000);

    return () => clearInterval(interval);
  }, [nextClaimTime]);

  const handleClaimProfit = () => {
    onClaimProfit(profitBreakdown.total, false);
    onClose();
  };

  const handleDoubleReward = () => {
    if (canDoubleReward) {
      onClaimProfit(profitBreakdown.total * 2, true);
      setCanDoubleReward(false);
      onClose();
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-[400px] max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="tracking-tight text-center font-bold flex items-center justify-center gap-2 mb-4 text-[26px]">
            <span style={{
              background: 'linear-gradient(135deg, #8B5CF6, #A855F7, #C084FC)',
              WebkitBackgroundClip: 'text',
              WebkitTextFillColor: 'transparent',
              backgroundClip: 'text',
              textShadow: '0 0 20px rgba(168, 85, 247, 0.5)',
              filter: 'drop-shadow(0 0 10px rgba(168, 85, 247, 0.3))'
            }}>
              Твой ежедневный доход
            </span>
            <span>💸</span>
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-4">
          <Card className="glass-dark">
            <CardContent className="p-4">
              {/* Profit Breakdown */}
              <div className="space-y-3 mb-4">
                <div className="flex justify-between items-center">
                  <span className="text-sm text-muted-foreground flex items-center gap-2">
                    🚗 Доход с автопарка:
                  </span>
                  <span className="text-sm font-semibold text-foreground">
                    {profitBreakdown.carFleetIncome.toLocaleString()} <span className="text-green-700 text-xs">₽</span>
                  </span>
                </div>

                <div className="flex justify-between items-center">
                  <span className="text-sm text-muted-foreground flex items-center gap-2">
                    💰 Кэшбек с тюнинга:
                  </span>
                  <span className="text-sm font-semibold text-foreground">
                    {profitBreakdown.tuningCashback.toLocaleString()} <span className="text-green-700 text-xs">₽</span>
                  </span>
                </div>

                <div className="flex justify-between items-center">
                  <span className="text-sm text-muted-foreground flex items-center gap-2">
                    📊 Бонус за активность:
                  </span>
                  <span className="text-sm font-semibold text-foreground">
                    {profitBreakdown.activityBonus.toLocaleString()} <span className="text-green-700 text-xs">₽</span>
                  </span>
                </div>

                {profitBreakdown.streakBonus > 0 && (
                  <div className="flex justify-between items-center">
                    <span className="text-sm text-muted-foreground flex items-center gap-2">
                      🔥 Серия дней ({dailyStreak}/7):
                    </span>
                    <span className="text-sm font-semibold text-green-400">
                      +{profitBreakdown.streakBonus.toLocaleString()} <span className="text-green-700 text-xs">₽</span>
                    </span>
                  </div>
                )}

                {/* Separator */}
                <div className="border-t border-muted-foreground/20 pt-2">
                  <div className="flex justify-between items-center">
                    <span className="text-base font-bold text-foreground flex items-center gap-2">
                      💵 ИТОГО:
                    </span>
                    <span className="text-xl font-bold text-green-400">
                      {profitBreakdown.total.toLocaleString()} <span className="text-green-700 text-lg">₽</span>
                    </span>
                  </div>
                </div>
              </div>

              {/* Action Buttons */}
              {canClaim ? (
                <div className="space-y-3">
                  <Button 
                    onClick={handleClaimProfit}
                    className="w-full glass-button bg-green-600 hover:bg-green-700 shadow-lg shadow-green-500/30 text-white font-bold"
                    size="lg"
                  >
                    Получить прибыль ▶
                  </Button>

                  {canDoubleReward && (
                    <Button 
                      onClick={handleDoubleReward}
                      className="w-full glass-button bg-purple-600 hover:bg-purple-700 shadow-lg shadow-purple-500/30 flex items-center justify-center gap-2 text-white font-bold"
                      size="lg"
                    >
                      📺 Увеличить x2
                    </Button>
                  )}
                </div>
              ) : (
                <div className="space-y-3">
                  <Button 
                    disabled
                    className="w-full glass-button opacity-50 cursor-not-allowed flex items-center justify-center gap-2"
                    size="lg"
                  >
                    <Shield className="h-4 w-4" />
                    Получить прибыль
                  </Button>

                  <div className="text-center">
                    <span className="text-sm text-muted-foreground">
                      🔁 Следующее начисление: через {timeLeft}
                    </span>
                  </div>
                </div>
              )}
            </CardContent>
          </Card>

          {/* Streak Info */}
          {dailyStreak > 0 && (
            <Card className="glass-dark border-yellow-500/30">
              <CardContent className="p-3">
                <div className="text-center">
                  <div className="text-yellow-400 font-semibold text-sm mb-1">
                    🔥 Серия: {dailyStreak} {dailyStreak === 1 ? 'день' : dailyStreak < 5 ? 'дня' : 'дней'}
                  </div>
                  <div className="text-xs text-muted-foreground">
                    Бонус: +{Math.min(dailyStreak * 5, 35)}% к доходу
                  </div>
                  <div className="text-xs text-muted-foreground">
                    До максимума: {Math.max(0, 7 - dailyStreak)} {Math.max(0, 7 - dailyStreak) === 1 ? 'день' : 'дней'}
                  </div>
                </div>
              </CardContent>
            </Card>
          )}

          {/* Close button for non-claimable state */}
          {!canClaim && (
            <Button 
              onClick={onClose}
              className="w-full glass-button"
              variant="outline"
            >
              Закрыть
            </Button>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

