import { useState, useEffect, useCallback } from 'react';
import { Achievement } from '@/components/AchievementCard';
import { achievements as initialAchievements } from '@/data/achievements';

interface AchievementData {
  achievements: Achievement[];
  totalXPEarned: number;
}

export function useAchievements() {
  const [achievementData, setAchievementData] = useState<AchievementData>(() => {
    try {
      const saved = localStorage.getItem('carTycoonAchievements');
      if (saved) {
        const parsed = JSON.parse(saved);
        return {
          achievements: parsed.achievements || initialAchievements,
          totalXPEarned: parsed.totalXPEarned || 0
        };
      }
    } catch (error) {
      console.error('Error loading achievements:', error);
    }

    return {
      achievements: initialAchievements,
      totalXPEarned: 0
    };
  });

  // Save to localStorage whenever data changes
  const saveAchievements = useCallback((data: AchievementData) => {
    try {
      localStorage.setItem('carTycoonAchievements', JSON.stringify(data));
    } catch (error) {
      console.error('Error saving achievements:', error);
    }
  }, []);

  // Update achievement progress
  const updateAchievementProgress = useCallback((achievementId: string, newProgress: number) => {
    setAchievementData(prev => {
      const updated = {
        ...prev,
        achievements: prev.achievements.map(achievement => {
          if (achievement.id === achievementId) {
            const updatedAchievement = {
              ...achievement,
              progress: Math.min(newProgress, achievement.maxProgress),
              completed: newProgress >= achievement.maxProgress
            };
            return updatedAchievement;
          }
          return achievement;
        })
      };

      saveAchievements(updated);
      return updated;
    });
  }, [saveAchievements]);

  // Increment achievement progress
  const incrementAchievementProgress = useCallback((achievementId: string, increment: number = 1) => {
    setAchievementData(prev => {
      const achievement = prev.achievements.find(a => a.id === achievementId);
      if (achievement) {
        const newProgress = achievement.progress + increment;
        return {
          ...prev,
          achievements: prev.achievements.map(a => 
            a.id === achievementId 
              ? {
                  ...a,
                  progress: Math.min(newProgress, a.maxProgress),
                  completed: newProgress >= a.maxProgress
                }
              : a
          )
        };
      }
      return prev;
    });
  }, []);

  // Claim achievement reward
  const claimAchievement = useCallback((achievementId: string, onReward: (coins: number, xp: number) => void) => {
    setAchievementData(prev => {
      const achievement = prev.achievements.find(a => a.id === achievementId);
      if (achievement && achievement.completed && !achievement.claimed) {
        // Grant the rewards
        onReward(achievement.coinReward, achievement.xpReward);

        const updated = {
          ...prev,
          achievements: prev.achievements.map(a => 
            a.id === achievementId ? { ...a, claimed: true } : a
          ),
          totalXPEarned: prev.totalXPEarned + achievement.xpReward
        };

        saveAchievements(updated);
        return updated;
      }
      return prev;
    });
  }, [saveAchievements]);

  // Get achievements by category, sorted by rarity (ascending)
  const getAchievementsByCategory = useCallback((category: string) => {
    const rarityOrder = { basic: 1, rare: 2, epic: 3, legendary: 4 };
    return achievementData.achievements
      .filter(a => a.category === category)
      .sort((a, b) => rarityOrder[a.rarity] - rarityOrder[b.rarity]);
  }, [achievementData.achievements]);

  // Get achievement stats
  const getAchievementStats = useCallback(() => {
    const total = achievementData.achievements.length;
    const completed = achievementData.achievements.filter(a => a.completed).length;
    const claimed = achievementData.achievements.filter(a => a.claimed).length;
    const availableToClaim = achievementData.achievements.filter(a => a.completed && !a.claimed).length;

    return {
      total,
      completed,
      claimed,
      availableToClaim,
      completionPercentage: Math.round((completed / total) * 100)
    };
  }, [achievementData.achievements]);

  // Helper functions for common achievement triggers
  const trackDetailingService = useCallback((serviceType: string) => {
    switch (serviceType) {
      case 'wash':
        updateAchievementProgress('washed_new', 1);
        incrementAchievementProgress('clean_play', 1);
        break;
      case 'polish':
        incrementAchievementProgress('polishing_plus', 1);
        incrementAchievementProgress('clean_play', 1);
        break;
      case 'interior':
        updateAchievementProgress('salon_new', 1);
        incrementAchievementProgress('clean_play', 1);
        break;
      case 'full_detailing':
        updateAchievementProgress('better_factory', 1);
        incrementAchievementProgress('clean_play', 1);
        break;
    }
  }, [updateAchievementProgress, incrementAchievementProgress]);

  const trackDailyProfitClaim = useCallback(() => {
    incrementAchievementProgress('working_days', 1);
  }, [incrementAchievementProgress]);

  const trackAdWatch = useCallback(() => {
    incrementAchievementProgress('viewer_investor', 1);
  }, [incrementAchievementProgress]);

  const trackTotalEarnings = useCallback((amount: number) => {
    setAchievementData(prev => {
      const current = prev.achievements.find(a => a.id === 'financial_genius');
      if (current) {
        const newProgress = current.progress + amount;
        updateAchievementProgress('financial_genius', newProgress);
      }
      return prev;
    });
  }, [updateAchievementProgress]);

  const trackCarPurchase = useCallback(() => {
    incrementAchievementProgress('collector_pts', 1);
    // Add logic for different car classes when implemented
  }, [incrementAchievementProgress]);

  const trackTuningUpgrade = useCallback((upgradeType: string) => {
    switch (upgradeType) {
      case 'turbine':
        incrementAchievementProgress('turbine_heart', 1);
        break;
      case 'exterior':
        incrementAchievementProgress('beauty_details', 1);
        break;
      case 'engine_swap':
        updateAchievementProgress('full_swap', 1);
        break;
      case 'wheels':
        updateAchievementProgress('tire_service', 1);
        break;
      case 'audio':
        updateAchievementProgress('audio_pro', 1);
        break;
    }
  }, [updateAchievementProgress, incrementAchievementProgress]);

  return {
    achievements: achievementData.achievements,
    totalXPEarned: achievementData.totalXPEarned,
    updateAchievementProgress,
    incrementAchievementProgress,
    claimAchievement,
    getAchievementsByCategory,
    getAchievementStats,
    // Helper functions
    trackDetailingService,
    trackDailyProfitClaim,
    trackAdWatch,
    trackTotalEarnings,
    trackCarPurchase,
    trackTuningUpgrade
  };
}

client/src/hooks/useGameState.ts.content:
import React, { useState, useEffect, useCallback } from 'react';

interface GameState {
  coins: number;
  level: number;
  energy: number;
  maxEnergy: number;
  hourlyIncome: number;
  boostsUsedToday: number;
  boostActive: boolean;
  boostEndTime: number;
  lastEnergyUpdate: number;
  introShown: boolean;
  totalClicks: number;
  lastRewardTime: number;
  lastProfitClaim: number;
  dailyStreak: number;
  selectedStarterCar?: any;
  ownedCars: any[];
  carMileage: number;  // Пробег автомобиля в км
  timeInGame: number;  // Время в игре в минутах
  totalUpgradeSpent: number;  // Общая сумма потраченная на улучшения
  sessionStartTime: number;  // Время начала текущей сессии
}

const INITIAL_STATE: GameState = {
  coins: 0,
  level: 1,
  energy: 1000,
  maxEnergy: 1000,
  hourlyIncome: 10,
  boostsUsedToday: 0,
  boostActive: false,
  boostEndTime: 0,
  lastEnergyUpdate: Date.now(),
  introShown: false,
  totalClicks: 0,
  lastRewardTime: 0,
  lastProfitClaim: 0,
  dailyStreak: 0,
  selectedStarterCar: undefined,
  ownedCars: [],
  carMileage: 0,  // Начальный пробег = 0
  timeInGame: 0,  // Время в игре = 0
  totalUpgradeSpent: 0,  // Потрачено на улучшения = 0
  sessionStartTime: Date.now(),  // Начало сессии
};

// Вспомогательные функции
const ENERGY_REGEN_RATE = 1000 / (10 * 60 * 1000); // 1000 энергии за 10 минут
const BOOST_DURATION = 5 * 60 * 1000; // 5 минут
const BOOST_MULTIPLIER = 1.5;
const COINS_PER_LEVEL = 100;
const REWARD_INTERVAL = 12 * 60 * 60 * 1000; // 12 часов

// Функция для вычисления требуемых кликов для уровня
const getClicksForLevel = (level: number): number => {
  if (level <= 1) return 0;
  return Math.floor(1000 * Math.pow(3, level - 2));
};

// Функция для вычисления уровня по кликам
const getLevelFromClicks = (clicks: number): number => {
  let level = 1;
  let totalClicks = 0;

  while (totalClicks + getClicksForLevel(level + 1) <= clicks) {
    totalClicks += getClicksForLevel(level + 1);
    level++;
  }

  return level;
};

// Функция для вычисления прогресса уровня
const getLevelProgress = (clicks: number, level: number): number => {
  const currentLevelClicks = getClicksForLevel(level);
  const nextLevelClicks = getClicksForLevel(level + 1);

  let totalClicksToCurrentLevel = 0;
  for (let i = 2; i <= level; i++) {
    totalClicksToCurrentLevel += getClicksForLevel(i);
  }

  const clicksInCurrentLevel = clicks - totalClicksToCurrentLevel;
  return (clicksInCurrentLevel / nextLevelClicks) * 100;
};

export function useGameState() {
  const [gameState, setGameState] = useState<GameState>(() => {
    try {
      // Проверяем флаг принудительного сброса
      const forceReset = localStorage.getItem('forceReset');
      if (forceReset === 'true') {
        // Очищаем все данные и удаляем флаг сброса
        localStorage.clear();
        console.log('Выполнен принудительный сброс всех пользователей');
        return INITIAL_STATE;
      }

      const savedState = localStorage.getItem('carTycoonGame');
      const savedIntro = localStorage.getItem('carTycoonIntro');

      let initialState = { ...INITIAL_STATE };

      if (savedState) {
        const parsed = JSON.parse(savedState);
        initialState = { ...initialState, ...parsed };
      }

      if (savedIntro === 'true') {
        initialState = { ...initialState, introShown: true };
      }

      return initialState;
    } catch (error) {
      console.error('Error loading game state:', error);
      return INITIAL_STATE;
    }
  });

  // Save game state to localStorage
  const saveGameState = useCallback((state: GameState) => {
    try {
      localStorage.setItem('carTycoonGame', JSON.stringify(state));

      if (state.introShown) {
        localStorage.setItem('carTycoonIntro', 'true');
      }
    } catch (error) {
      console.error('Error saving game state:', error);
    }
  }, []);

  // Update game state and save
  const updateGameState = useCallback((updates: Partial<GameState>) => {
    setGameState(prev => {
      const newState = { ...prev, ...updates };
      saveGameState(newState);
      return newState;
    });
  }, [saveGameState]);

  // Восстановление энергии
  const updateEnergy = useCallback(() => {
    const now = Date.now();
    const timeDiff = now - gameState.lastEnergyUpdate;
    const energyToAdd = Math.floor(timeDiff * ENERGY_REGEN_RATE);

    if (energyToAdd > 0) {
      const newEnergy = Math.min(gameState.energy + energyToAdd, gameState.maxEnergy);
      updateGameState({
        energy: newEnergy,
        lastEnergyUpdate: now,
      });
    }
  }, [gameState.energy, gameState.maxEnergy, gameState.lastEnergyUpdate, updateGameState]);

  // Проверка и завершение буста
  const checkBoostExpired = useCallback(() => {
    if (gameState.boostActive && Date.now() > gameState.boostEndTime) {
      updateGameState({
        boostActive: false,
        boostEndTime: 0,
      });
    }
  }, [gameState.boostActive, gameState.boostEndTime, updateGameState]);

  // Обновление уровня
  const updateLevel = useCallback((totalClicks: number) => {
    const newLevel = getLevelFromClicks(totalClicks);
    if (newLevel !== gameState.level) {
      updateGameState({ level: newLevel });
    }
  }, [gameState.level, updateGameState]);

  // Заработать монеты (клик)
  const earnCoins = useCallback(() => {
    if (gameState.energy <= 0) return false;

    const multiplier = gameState.boostActive ? BOOST_MULTIPLIER : 1;
    const coinsEarned = Math.floor(1 * multiplier);
    const newCoins = gameState.coins + coinsEarned;
    const newTotalClicks = gameState.totalClicks + 1;

    // Увеличиваем пробег: +1км за каждые 100 кликов
    const newMileage = Math.floor(newTotalClicks / 100);

    updateGameState({
      coins: newCoins,
      energy: gameState.energy - 1,
      totalClicks: newTotalClicks,
      carMileage: newMileage,
    });

    updateLevel(newTotalClicks);
    return true;
  }, [gameState.coins, gameState.energy, gameState.boostActive, gameState.totalClicks, updateGameState, updateLevel]);

  // Активировать буст
  const activateBoost = useCallback(() => {
    if (gameState.boostsUsedToday >= 2 || gameState.boostActive) return false;

    const boostEndTime = Date.now() + BOOST_DURATION;
    const newMaxEnergy = Math.floor(gameState.maxEnergy * BOOST_MULTIPLIER);

    updateGameState({
      boostActive: true,
      boostEndTime,
      boostsUsedToday: gameState.boostsUsedToday + 1,
      maxEnergy: newMaxEnergy,
      energy: Math.min(gameState.energy, newMaxEnergy),
    });

    return true;
  }, [gameState.boostsUsedToday, gameState.boostActive, gameState.maxEnergy, gameState.energy, updateGameState]);

  // Complete intro
  const completeIntro = useCallback((selectedCar?: any) => {
    const updates: Partial<GameState> = { introShown: true };

    // If a car was selected, store it as owned car (no money given)
    if (selectedCar) {
      updates.selectedStarterCar = selectedCar;
      // Add the car to owned cars array
      updates.ownedCars = [selectedCar];
      // Set starting coins to default amount (no car price bonus)
      updates.coins = 100; // Small starting amount for game progression
    }

    updateGameState(updates);
  }, [updateGameState]);

  // Reset intro for all users (admin function)
  const resetIntroForAllUsers = useCallback(() => {
    // Clear localStorage intro flag
    localStorage.removeItem('carTycoonIntro');
    // Reset intro state
    updateGameState({ introShown: false });
  }, [updateGameState]);

  // Reset all users to initial screen (admin function)
  const resetAllUsersToInitial = useCallback(() => {
    // Set force reset flag - will trigger on next app load
    localStorage.setItem('forceReset', 'true');
    // Also immediately reset current user including mileage
    localStorage.clear();
    setGameState(INITIAL_STATE);
    console.log('Все пользователи сброшены: пробег = 0км, клики = 0');
    // Force page reload to apply changes
    window.location.reload();
  }, []);

  // Track upgrade spending for cashback calculation
  const addUpgradeSpending = useCallback((amount: number) => {
    updateGameState({ 
      totalUpgradeSpent: gameState.totalUpgradeSpent + amount 
    });
  }, [gameState.totalUpgradeSpent, updateGameState]);

  // Проверка доступности награды
  const canClaimReward = useCallback(() => {
    const now = Date.now();
    return now - gameState.lastRewardTime >= REWARD_INTERVAL;
  }, [gameState.lastRewardTime]);

  // Получить награду (старая система)
  const claimReward = useCallback(() => {
    const canClaim = Date.now() - gameState.lastRewardTime >= REWARD_INTERVAL;
    if (!canClaim) return false;

    const rewardAmount = Math.floor(gameState.hourlyIncome * 10);
    const newCoins = gameState.coins + rewardAmount;

    updateGameState({
      coins: newCoins,
      lastRewardTime: Date.now(),
    });

    return true;
  }, [gameState.coins, gameState.hourlyIncome, gameState.lastRewardTime, updateGameState]);

  // Проверка доступности ежедневной прибыли
  const canClaimDailyProfit = useCallback(() => {
    const now = Date.now();
    return now - gameState.lastProfitClaim >= REWARD_INTERVAL;
  }, [gameState.lastProfitClaim]);

  // Получить ежедневную прибыль
  const claimDailyProfit = useCallback((amount: number, isDoubled: boolean) => {
    const now = Date.now();
    const canClaim = now - gameState.lastProfitClaim >= REWARD_INTERVAL;
    if (!canClaim) return false;

    const newCoins = gameState.coins + amount;

    // Update daily streak logic
    const lastClaimDate = new Date(gameState.lastProfitClaim).toDateString();
    const todayDate = new Date().toDateString();
    const yesterdayDate = new Date(Date.now() - 24 * 60 * 60 * 1000).toDateString();

    let newStreak = gameState.dailyStreak;

    if (gameState.lastProfitClaim === 0) {
      // First time claiming
      newStreak = 1;
    } else if (lastClaimDate === yesterdayDate) {
      // Claimed yesterday, continue streak
      newStreak = Math.min(gameState.dailyStreak + 1, 7);
    } else if (lastClaimDate !== todayDate) {
      // Missed days, reset streak
      newStreak = 1;
    }

    updateGameState({
      coins: newCoins,
      lastProfitClaim: now,
      dailyStreak: newStreak,
    });

    return true;
  }, [gameState.coins, gameState.lastProfitClaim, gameState.dailyStreak, updateGameState]);

  // Сброс ежедневных бустов (можно вызывать в начале нового дня)
  const resetDailyBoosts = useCallback(() => {
    updateGameState({ boostsUsedToday: 0 });
  }, [updateGameState]);

  // Get current owned car (primary car for garage display)
  const getCurrentCar = useCallback(() => {
    // First check owned cars array
    if (gameState.ownedCars && gameState.ownedCars.length > 0) {
      return gameState.ownedCars[0]; // Return the first (primary) owned car
    }

    // Fallback to selected starter car
    if (gameState.selectedStarterCar) {
      return gameState.selectedStarterCar;
    }

    // Last fallback - check localStorage for legacy data
    try {
      const storedCar = localStorage.getItem('selectedStarterCar');
      if (storedCar) {
        const car = JSON.parse(storedCar);
        // Migrate to owned cars array
        updateGameState({ ownedCars: [car] });
        return car;
      }
    } catch (error) {
      console.error('Error retrieving stored car:', error);
    }

    return null;
  }, [gameState.ownedCars, gameState.selectedStarterCar, updateGameState]);

  // Периодические обновления
  useEffect(() => {
    const interval = setInterval(() => {
      updateEnergy();
      checkBoostExpired();

      // Обновляем время в игре каждую минуту
      const now = Date.now();
      const sessionDuration = Math.floor((now - gameState.sessionStartTime) / (60 * 1000)); // в минутах
      if (sessionDuration > 0) {
        updateGameState({ 
          timeInGame: gameState.timeInGame + sessionDuration,
          sessionStartTime: now 
        });
      }

      saveGameState(gameState);
    }, 60000); // Обновляем каждую минуту

    return () => clearInterval(interval);
  }, [gameState, updateEnergy, checkBoostExpired, saveGameState, updateGameState]);

  // Вычисляемые значения
  const canClick = gameState.energy > 0;
  const canBoost = gameState.boostsUsedToday < 2 && !gameState.boostActive;
  const levelProgress = getLevelProgress(gameState.totalClicks, gameState.level);
  const boostTimeLeft = gameState.boostActive ? Math.max(0, gameState.boostEndTime - Date.now()) : 0;

  return {
    gameState,
    earnCoins,
    activateBoost,
    completeIntro,
    updateGameState,
    resetDailyBoosts,
    resetIntroForAllUsers,
    resetAllUsersToInitial,
    addUpgradeSpending,
    canClaimReward,
    claimReward,
    canClaimDailyProfit,
    claimDailyProfit,
    getCurrentCar,
    canClick,
    canBoost,
    levelProgress,
    boostTimeLeft,
  };
}

